package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.rate.Rate;

/**
 * The figures of one person's claims, as the screen works them out: a settled claim's frozen due, else the
 * figure its person's last statement bound it to, else its live due (amount times its grade's rate in force on
 * its date, rounded half to even; none — n/a — when no rate applies then).
 */
public class ClaimFigures {

    private final List<Rate> rates;

    /** @param rates the rates of the person's grade. */
    public ClaimFigures(List<Rate> rates) {
        this.rates = rates;
    }

    /** Whether a claim counts toward the totals: only OPEN and SETTLED claims do. */
    public static boolean counts(Claim claim) {
        return claim.getStatus() == ClaimStatus.OPEN || claim.getStatus() == ClaimStatus.SETTLED;
    }

    /** Whether a claim counts toward the live totals: as {@link #counts}, except a held person's OPEN claims. */
    public static boolean countsLive(Claim claim, boolean held) {
        return counts(claim) && !(held && claim.getStatus() == ClaimStatus.OPEN);
    }

    private Optional<BigDecimal> rateOn(LocalDate on) {
        return rates.stream()
                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(on))
                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .map(Rate::getPct);
    }

    /** The claim's figure; null when it has none (n/a). */
    public BigDecimal figure(Claim claim) {
        if (claim.getDue() != null) {
            return claim.getDue();
        }
        if (claim.isStated()) {
            return claim.getStatedDue();
        }
        return rateOn(claim.getDate())
                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN))
                .orElse(null);
    }

    /** The person's due-total: their counted claims' figures added up, 0.00 with none; n/a when their grade has
     *  no rate in force on the day, unless a counted claim keeps a fixed figure (settled or bound). */
    public String dueTotal(List<Claim> claims, LocalDate today) {
        return dueTotal(claims, today, false);
    }

    /** The person's live due-total, as {@link #dueTotal(List, LocalDate)}; while they are held their OPEN
     *  claims do not count. */
    public String dueTotal(List<Claim> claims, LocalDate today, boolean held) {
        List<Claim> counted = claims.stream().filter(c -> countsLive(c, held)).toList();
        boolean fixed = counted.stream().anyMatch(c -> c.getDue() != null || (c.isStated() && c.getStatedDue() != null));
        if (rateOn(today).isEmpty() && !fixed) {
            return "n/a";
        }
        return counted.stream().map(this::figure).filter(f -> f != null)
                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimFigures;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;

/**
 * The sheet's figures at one moment, as the screen shows them: each person's claimed and due-total, in the
 * order they were added, and the sheet's claimed-total and due-total (everyone's added up, skipping n/a).
 * A held person's OPEN claims count in none of them.
 */
public class Rollup {

    /** One person's figures. */
    public record Figures(String name, String claimed, String dueTotal) {
    }

    private final Map<Long, Figures> people;
    private final String claimedTotal;
    private final String dueTotal;

    private Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal) {
        this.people = people;
        this.claimedTotal = claimedTotal;
        this.dueTotal = dueTotal;
    }

    /** Works out the sheet's figures now; a sheet not yet stored has none. */
    public static Rollup of(String sheetId, SheetRepository sheets, PersonRepository persons,
            ClaimRepository claims, RateRepository rates) {
        String id = sheetId.trim();
        Optional<Sheet> sheet = sheets.findById(id);
        Map<Long, Figures> people = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO;
        BigDecimal dueTotal = BigDecimal.ZERO;
        if (sheet.isPresent()) {
            List<Claim> all = claims.findBySheetIdOrderByIdDesc(id);
            for (Person person : persons.findBySheetIdOrderByIdAsc(id)) {
                List<Claim> mine = all.stream().filter(c -> person.getId().equals(c.getPersonId())).toList();
                BigDecimal claimed = mine.stream().filter(c -> ClaimFigures.countsLive(c, person.isHeld())).map(Claim::getAmount)
                        .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
                String due = new ClaimFigures(rates.findBySheetIdAndGrade(id, person.getGrade()))
                        .dueTotal(mine, sheet.get().getToday(), person.isHeld());
                people.put(person.getId(), new Figures(person.getName(), claimed.toPlainString(), due));
                claimedTotal = claimedTotal.add(claimed);
                if (!"n/a".equals(due)) {
                    dueTotal = dueTotal.add(new BigDecimal(due));
                }
            }
        }
        return new Rollup(people, claimedTotal.setScale(2).toPlainString(), dueTotal.setScale(2).toPlainString());
    }

    /** The audit lines telling how the figures moved from before to now: one per person whose figures changed
     *  (or who is new), then the totals when they changed; none when nothing moved. */
    public List<String> changesSince(Rollup before, String sheetId, String user) {
        String head = " sheet=" + sheetId.trim() + " by=" + user;
        List<String> lines = new ArrayList<>();
        people.forEach((id, now) -> {
            Figures was = before.people.get(id);
            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())) {
                lines.add("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed()
                        + " due-total=" + now.dueTotal());
            }
        });
        if (!before.claimedTotal.equals(claimedTotal) || !before.dueTotal.equals(dueTotal)) {
            lines.add("TOTALS" + head + " claimed-total=" + claimedTotal + " due-total=" + dueTotal);
        }
        return lines;
    }
}
