package net.officefloor.hq.app.statement;

import jakarta.persistence.EntityManager;
import jakarta.persistence.LockModeType;
import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimFigures;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes a statement for the person: records their due-total now, on the sheet's today, and binds each of
 * their claims that counts to the figure it has now; their claims that do not count are unbound (live again).
 */
public class TakeStatement {
    public void take(@Val Sheet sheet, @Val Person person, ClaimRepository claims, RateRepository rates,
            StatementRepository statements, EntityManager entityManager, Out<Statement> statementOut) {
        // Lock the person so two statements (or a statement and an edit) are taken one after the other.
        entityManager.refresh(person, LockModeType.PESSIMISTIC_WRITE);
        List<Claim> mine = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheet.getId(), person.getId());
        ClaimFigures figures = new ClaimFigures(rates.findBySheetIdAndGrade(sheet.getId(), person.getGrade()));
        String dueTotal = figures.dueTotal(mine, sheet.getToday());
        int counted = 0;
        for (Claim claim : mine) {
            if (ClaimFigures.counts(claim)) {
                BigDecimal figure = figures.figure(claim);
                claim.bind(true, figure);
                counted++;
            } else {
                claim.bind(false, null);
            }
        }
        claims.saveAllAndFlush(mine);
        statementOut.set(statements.save(
                new Statement(sheet.getId(), person.getId(), dueTotal, sheet.getToday(), counted)));
    }
}
package net.officefloor.hq.app.period;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A sheet's period: a name (unique on the sheet) and a from and to date, inclusive; once closed, its due-total
 *  is fixed at what it was on closing. */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date", nullable = false)
    private LocalDate toDate;

    /** Whether the period is closed: no claim dated in it can be added, edited or change status. */
    @Column(nullable = false)
    private boolean closed;

    /** The due-total fixed when the period was closed; null while it is open. */
    @Column(name = "closed_total", precision = 19, scale = 2)
    private BigDecimal closedTotal;

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
        this.sheetId = sheetId;
        this.name = name;
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    public boolean isClosed() {
        return closed;
    }

    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    /** Closes the period, fixing its due-total. */
    public void close(BigDecimal total) {
        this.closed = true;
        this.closedTotal = total;
    }

    /** Whether a date falls in this period (inclusive). */
    public boolean contains(LocalDate date) {
        return !date.isBefore(fromDate) && !date.isAfter(toDate);
    }

    /** Whether this period's dates overlap the given ones (both inclusive). */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !fromDate.isAfter(to) && !from.isAfter(toDate);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.ClaimFigures;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.plugin.variable.Val;

/** Closes the period, fixing its due-total as it is now: the figures of the counted claims dated in it (not a held
 *  person's OPEN ones), added up, skipping n/a. Refuses a period already closed. */
public class ClosePeriod {
    public void close(@Val Period period, PeriodRepository repository, ClaimRepository claims, PersonRepository people,
            RateRepository rates) throws InvalidPeriodException {
        if (period.isClosed()) {
            throw new InvalidPeriodException("The period is already closed.");
        }
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(period.getSheetId()).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        BigDecimal total = claims.findBySheetIdOrderByIdDesc(period.getSheetId()).stream()
                .filter(c -> byId.containsKey(c.getPersonId()) && ClaimFigures.countsLive(c, byId.get(c.getPersonId()).isHeld())
                        && period.contains(c.getDate()))
                .map(c -> new ClaimFigures(rates.findBySheetIdAndGrade(period.getSheetId(),
                        byId.get(c.getPersonId()).getGrade())).figure(c))
                .filter(f -> f != null)
                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
        period.close(total);
        repository.saveAndFlush(period);
    }
}
